package com.podhod.app;
import android.widget.*;
import org.json.*;
final class IntermediateUi {
 static void panel(MainActivity a,LinearLayout parent,JSONObject p,boolean inline){LinearLayout c=inline?parent:a.card(parent);c.addView(a.title(Lang.t("Злат · intermediate"),22));c.addView(a.text(Lang.t("Объём → техника → контроль. Прибавки 1,25 или 2,5 кг, только после подтверждения результата."),14,a.MUTED));JSONObject weights=p.optJSONObject("intermediateWeights");if(weights!=null)for(String lift:new String[]{"pullup","dip"}){JSONObject w=weights.optJSONObject(lift);c.addView(a.text(Lang.t(lift.equals("pullup")?"Турник":"Брусья")+" · "+Engine.number(w.optDouble("heavy"))+Lang.t(" кг"),18,a.GREEN));}a.button(c,Lang.t("Настроить начальные веса"),false,()->setup(a,p,()->{}));a.hint(c,Lang.t("Правила и источник"),Lang.t("Старт: тяжёлый вес — 80% от 1ПМ, объёмный — 65%, лёгкий — 70% тяжёлого. Округление вниз до 1,25 кг. Далее тяжёлый и лёгкий веса растут на одну прибавку по контрольному дню; объёмный блок — отдельно по минимуму повторов. 6+ повторов: +2,5 кг; 5: +1,25 кг; 4 и меньше: вес остаётся. Облегчённые подходы контрольного дня: −15 кг на турнике, −20 кг на брусьях, минимум 0 кг. Это адаптация без микроблинов и ежемесячного теста 1ПМ."));a.link(c,Lang.t("Источник программы"),()->a.startActivity(new android.content.Intent(android.content.Intent.ACTION_VIEW,android.net.Uri.parse(p.optString("source")))));}
 static void setup(MainActivity a,JSONObject p,Runnable after){LinearLayout box=a.form();box.addView(a.text(Lang.t("Введи известный максимум дополнительного веса на одно повторение. Массу тела не добавляй. Настройка пересчитает будущие занятия."),14,a.MUTED));EditText pull=a.input(box,Lang.t("Турник · 1ПМ, кг"),"",true),dip=a.input(box,Lang.t("Брусья · 1ПМ, кг"),"",true);a.formDialog(Lang.t("Начальные веса"),box,Lang.t("Сохранить"),()->{ZlatIntermediate.configure(p,a.positive(pull,false),a.positive(dip,false));a.store.save();a.render();after.run();});}
 static void finish(MainActivity a,JSONObject s){if(Engine.doneCount(s)!=s.optJSONArray("sets").length())return;LinearLayout box=a.form();box.addView(a.text(Lang.t("Проверь фактические повторы в подходах. Для объёмного блока учитывается худший подход, для контрольного — первый тяжёлый. При необходимости вернись и исправь повторы."),14,a.MUTED));java.util.ArrayList<EditText> inputs=new java.util.ArrayList<>();java.util.ArrayList<JSONObject> targets=new java.util.ArrayList<>();JSONArray sets=s.optJSONArray("sets");for(int i=0;i<sets.length();i++){JSONObject set=sets.optJSONObject(i);String block=set.optString("intermediateBlock");if(!block.equals("test")&&!block.equals("volume"))continue;String lift=set.optString("intermediateLift");targets.add(set);inputs.add(a.input(box,Lang.t(lift.equals("pullup")?"Турник":"Брусья")+" · "+Lang.t("Подход ")+set.optInt("ordinal"),String.valueOf(set.optInt("reps")),true));}box.addView(a.text(Lang.t("6+ повторов: +2,5 кг · 5: +1,25 кг · 4 и меньше: без прибавки"),14,a.GREEN));int revision=s.optInt("revision");a.formDialog(Lang.t("Результат занятия"),box,Lang.t("Сохранить и рассчитать веса"),()->{if(a.store.active()!=s||revision!=s.optInt("revision"))throw new IllegalArgumentException(Lang.t("Подходы изменились. Открой сохранение заново."));int[] reps=new int[inputs.size()];for(int i=0;i<inputs.size();i++)reps[i]=a.integer(inputs.get(i),1000);for(int i=0;i<inputs.size();i++)Engine.put(targets.get(i),"reps",reps[i]);Engine.put(s,"confirmedRevision",revision);a.act("finish");});}
}
